from pathlib import Path
import re
p = Path('/home/ubuntu/entertainment-tracker/client/src/pages/Home.tsx')
s = p.read_text()
s = s.replace('onRefreshMetadata, refreshing }: { items: MediaItem[]; activeType:', 'onRefreshMetadata, refreshing, onSchedule }: { items: MediaItem[]; activeType:')
s = s.replace('onRefreshMetadata: () => void; refreshing: boolean }) {', 'onRefreshMetadata: () => void; refreshing: boolean; onSchedule: (item: MediaItem, value: string) => void }) {', 1)
old = '<p>{item.detail}</p>{item.progress > 0 &&'
new = '<p>{item.detail}</p><label className="schedule-field" onClick={(event) => event.stopPropagation()}><CalendarDays size={12} /><span>{item.scheduledDate ? "Scheduled" : "Schedule"}</span><input type="date" value={item.scheduledDate ?? ""} onChange={(event) => onSchedule(item, event.target.value)} /></label>{item.progress > 0 &&'
if old not in s:
    raise SystemExit('library insertion target not found')
